import type {LocalizedString} from '@weavix/tracker-api-types';

export function useLocalizedString(messages: Record<string, LocalizedString>, language = 'ru') {
    const t = (key: string, params?: Record<string, unknown>): string => {
        const message = messages[key]?.[language as keyof LocalizedString] || key;
        if (params) {
            let result: string = message;
            Object.entries(params).forEach(([k, v]) => {
                result = result.replace(`{${k}}`, String(v));
            });
            return result;
        }
        return message;
    };

    return {t};
}
